-- QR Menü: kapak fotoğrafı, duyuru şeridi ve kategori görseli sütunları + demo menüleri zenginleştirme
begin;
alter table public.qr_menuler add column if not exists kapak text not null default '';
alter table public.qr_menuler add column if not exists duyuru text not null default '';
alter table public.qr_menuler add column if not exists duyuru_en text not null default '';
alter table public.qr_kategoriler add column if not exists gorsel text not null default '';
