insert into public.qr_urunler (kategori_id, sira, ad, ad_en, aciklama, aciklama_en, fiyat, fiyat2, fiyatlar, alerjenler, etiket, gorsel, tukendi, aktif)
select k.id, 100, r.ad, r.ad_en, r.aciklama, r.aciklama_en, r.fiyat, r.fiyat2, r.fiyatlar, r.alerjenler, r.etiket, r.gorsel, r.tukendi, r.aktif
from json_populate_record(null::public.qr_urunler, $j${"ad": "Çikolatalı Milkshake", "ad_en": "Chocolate Milkshake", "aciklama": "Vanilyalı dondurma, çikolata sosu", "aciklama_en": "", "fiyat": 165, "fiyat2": null, "fiyatlar": [165], "alerjenler": ["D"], "etiket": "Yeni", "gorsel": "https://images.unsplash.com/photo-1505252585461-04db1eb84625?w=640&h=480&fit=crop&q=70&auto=format", "tukendi": false, "aktif": true}$j$) r, public.qr_kategoriler k join public.qr_menuler m on m.id = k.menu_id
where m.slug = 'cafe' and k.ad = 'Soğuk İçecekler' and not exists (select 1 from public.qr_urunler x where x.kategori_id = k.id and x.ad = r.ad);
