where m.slug = 'burger' and k.ad = 'İçecekler' and not exists (select 1 from public.qr_urunler x where x.kategori_id = k.id and x.ad = r.ad);
commit;
select m.slug, m.duyuru, (select count(*) from public.qr_kategoriler k where k.menu_id=m.id and k.gorsel<>'') as kategori_gorseli, (select count(*) from public.qr_urunler u join public.qr_kategoriler k on k.id=u.kategori_id where k.menu_id=m.id and u.gorsel<>'') as urun_gorseli from public.qr_menuler m where m.slug in ('restoran','cafe','burger','lokanta','bar') order by m.slug;
